"""SQL for re-sorting operations."""
GET_LOCATION_BY_CODE = (
    "SELECT location_id,location_code,name,is_active FROM wms.locations WHERE location_code=$1"
)
GET_ACTIVE_OPERATION_LOCATION_FOR_SHARE = """SELECT operation_location_id,operation_code,location_id,location_code,scope,is_active,author,metadata,created_at,updated_at FROM wms.operation_locations WHERE operation_code='re_sorting_operations' AND scope='direct' AND location_code=$1 AND location_id=$2 AND is_active=TRUE FOR SHARE"""
LIST_OPERATION_LOCATIONS = """SELECT ol.operation_location_id,ol.operation_code,ol.location_id,ol.location_code,l.name AS location_name,ol.scope,ol.is_active,ol.author,ol.metadata,ol.created_at,ol.updated_at FROM wms.operation_locations ol JOIN wms.locations l ON l.location_id=ol.location_id WHERE ol.operation_code='re_sorting_operations' AND ol.scope='direct' AND ($1::boolean IS NULL OR ol.is_active=$1) ORDER BY ol.created_at DESC,ol.operation_location_id DESC LIMIT $2 OFFSET $3"""
COUNT_OPERATION_LOCATIONS = "SELECT count(*)::int FROM wms.operation_locations WHERE operation_code='re_sorting_operations' AND scope='direct' AND ($1::boolean IS NULL OR is_active=$1)"
CREATE_OR_REACTIVATE_OPERATION_LOCATION = """INSERT INTO wms.operation_locations(operation_code,location_id,location_code,scope,is_active,author,metadata) VALUES('re_sorting_operations',$1,$2,'direct',TRUE,$3,COALESCE($4::jsonb,'{}'::jsonb)) ON CONFLICT(operation_code,location_id,scope) DO UPDATE SET location_code=EXCLUDED.location_code,is_active=TRUE,author=EXCLUDED.author,metadata=EXCLUDED.metadata,updated_at=NOW() RETURNING operation_location_id,operation_code,location_id,location_code,scope,is_active,author,metadata,created_at,updated_at"""
GET_OPERATION_LOCATION = "SELECT operation_location_id,operation_code,location_id,location_code,scope,is_active,author,metadata,created_at,updated_at FROM wms.operation_locations WHERE operation_location_id=$1 AND operation_code='re_sorting_operations' AND scope='direct'"
DEACTIVATE_OPERATION_LOCATION = "UPDATE wms.operation_locations SET is_active=FALSE,author=$2,updated_at=NOW() WHERE operation_location_id=$1 AND operation_code='re_sorting_operations' AND scope='direct' RETURNING operation_location_id,operation_code,location_id,location_code,scope,is_active,author,metadata,created_at,updated_at"
GET_PRODUCTS = "SELECT id,is_active,is_kit FROM public.products WHERE id=ANY($1::varchar[])"
LOCK_OPERATION_SCOPE = "SELECT pg_advisory_xact_lock(hashtextextended($1,0))"
GET_LOOSE_INVENTORY_FOR_UPDATE = "SELECT inventory_id,quantity FROM wms.inventory WHERE product_id=$1 AND location_id=$2 AND status='available' AND batch_number IS NULL AND container_code IS NULL FOR UPDATE"
GET_NON_LOOSE_INVENTORY_QUANTITY = "SELECT COALESCE(sum(quantity),0)::numeric FROM wms.inventory WHERE product_id=$1 AND location_id=$2 AND status='available' AND (batch_number IS NOT NULL OR container_code IS NOT NULL)"
CREATE_OPERATION = """INSERT INTO wms.re_sorting_operations(operation_location_id,from_product_id,to_product_id,quantity,location_id,location_code,reason,author,status,metadata) VALUES($1,$2,$3,$4,$5,$6,$7,$8,'processing','{}'::jsonb) RETURNING *"""
CREATE_ITEM = "INSERT INTO wms.re_sorting_operation_items(operation_id,role,product_id,quantity) VALUES($1,$2,$3,$4) RETURNING item_id,operation_id,role,product_id,quantity,movement_id,movement_created_at,created_at"
CREATE_MOVEMENT = """INSERT INTO wms.movements(movement_type,product_id,from_location_id,to_location_id,quantity,batch_number,container_code,user_name,reason,metadata,source_type,source_id,source_item_id) VALUES('re_sorting',$1,$2,$3,$4,NULL,NULL,$5,$6,$7::jsonb,'re_sorting_operation',$8,$9) RETURNING movement_id,created_at"""
SET_ITEM_MOVEMENT = "UPDATE wms.re_sorting_operation_items SET movement_id=$2,movement_created_at=$3 WHERE item_id=$1 RETURNING item_id,operation_id,role,product_id,quantity,movement_id,movement_created_at,created_at"
COMPLETE_OPERATION = "UPDATE wms.re_sorting_operations SET status='completed',completed_at=NOW(),updated_at=NOW() WHERE operation_id=$1 RETURNING *"
GET_OPERATION = "SELECT * FROM wms.re_sorting_operations WHERE operation_id=$1"
GET_ITEMS = "SELECT item_id,operation_id,role,product_id,quantity,movement_id,movement_created_at,created_at FROM wms.re_sorting_operation_items WHERE operation_id=$1 ORDER BY item_id"
LIST_OPERATIONS = """SELECT * FROM wms.re_sorting_operations WHERE ($1::varchar IS NULL OR from_product_id=$1) AND ($2::varchar IS NULL OR to_product_id=$2) AND ($3::varchar IS NULL OR status=$3) AND ($4::varchar IS NULL OR location_code=$4) AND ($5::timestamptz IS NULL OR created_at >= $5) AND ($6::timestamptz IS NULL OR created_at <= $6) ORDER BY created_at DESC LIMIT $7 OFFSET $8"""
